import io
import runpy
import sys
import unittest
from unittest.mock import patch

DESIRED = "WRITING PROGRAMS OR PROGRAMMING IS A VERY CREATIVE\nAND REWARDING ACTIVITY  YOU CAN WRITE PROGRAMS FOR\nMANY REASONS RANGING FROM MAKING YOUR LIVING TO SOLVING\nA DIFFICULT DATA ANALYSIS PROBLEM TO HAVING FUN TO HELPING\nSOMEONE ELSE SOLVE A PROBLEM  THIS BOOK ASSUMES THAT\n{\\EM EVERYONE} NEEDS TO KNOW HOW TO PROGRAM AND THAT ONCE\nYOU KNOW HOW TO PROGRAM, YOU WILL FIGURE OUT WHAT YOU WANT\nTO DO WITH YOUR NEWFOUND SKILLS\n\nWE ARE SURROUNDED IN OUR DAILY LIVES WITH COMPUTERS RANGING\nFROM LAPTOPS TO CELL PHONES  WE CAN THINK OF THESE COMPUTERS\nAS OUR PERSONAL ASSISTANTS WHO CAN TAKE CARE OF MANY THINGS\nON OUR BEHALF  THE HARDWARE IN OUR CURRENT-DAY COMPUTERS\nIS ESSENTIALLY BUILT TO CONTINUOUSLY AS US THE QUESTION\nWHAT WOULD YOU LIKE ME TO DO NEXT\n\nOUR COMPUTERS ARE FAST AND HAVE VASTS AMOUNTS OF MEMORY AND\nCOULD BE VERY HELPFUL TO US IF WE ONLY KNEW THE LANGUAGE TO\nSPEAK TO EXPLAIN TO THE COMPUTER WHAT WE WOULD LIKE IT TO\nDO NEXT IF WE KNEW THIS LANGUAGE WE COULD TELL THE\nCOMPUTER TO DO TASKS ON OUR BEHALF THAT WERE REPTITIVE\nINTERESTINGLY, THE KINDS OF THINGS COMPUTERS CAN DO BEST\nARE OFTEN THE KINDS OF THINGS THAT WE HUMANS FIND BORING\nAND MIND-NUMBING"
DESIRED2 = None
STDIN = "words.txt\n"


def run_student(stdin=STDIN):
    output = io.StringIO()
    with patch('builtins.input', side_effect=_input_side_effect(stdin)):
        with patch('sys.stdout', output):
            try:
                runpy.run_path('student.py', run_name='__main__')
            except SystemExit:
                pass
    return output.getvalue()


def _input_side_effect(stdin):
    lines = stdin.splitlines()
    # Preserve trailing blank semantics for programs that call input() once per line
    if stdin.endswith('\n'):
        # splitlines drops final empty; reconstruct queue of lines without newlines
        pass
    queue = list(lines)

    def _input(prompt=''):
        if not queue:
            raise EOFError('EOF when reading a line')
        return queue.pop(0)

    return _input


class OutputTests(unittest.TestCase):
    def test_desired_output(self):
        got = run_student().rstrip()
        # Normalize trailing whitespace per line for friendlier comparison
        got_norm = '\n'.join(line.rstrip() for line in got.splitlines()).rstrip()
        want = DESIRED.rstrip() if isinstance(DESIRED, str) else DESIRED
        alts = [want]
        if DESIRED2:
            alts.append(DESIRED2.rstrip())
        if got_norm not in alts:
            self.assertEqual(got_norm, want)


class SourceTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        with open('student.py', encoding='utf-8') as f:
            cls.src = f.read()

    def test_source_input(self):
        self.assertIn("input", self.src,
            "You must prompt for the file name using the input() function.")

    def test_source_open(self):
        self.assertIn("open", self.src,
            "You need to use open() to open the file.")

    def test_source_print(self):
        self.assertIn("print", self.src,
            "You must use the print function to print the lines.")

    def test_source_strip(self):
        self.assertIn("strip", self.src,
            "You should use strip() or rstrip() to avoid double newlines.")

    def test_source_upper(self):
        self.assertIn("upper", self.src,
            "You should use the upper() function to convert the lines to upper case.")
